func FwCopyWord(fw *port.Cells, words *port.Cells, w int32, line int32) int32 {
	// Append a copy of row w of `words` (the evidence's) to `fw`, pointing at `line` of `fl`; answers its row.
	var r int32 = plPush(fw, 24)
	var k int32 = 0
	for k < 24 {
		port.CellsSet(fw, (r*24)+k, port.CellsAt(words, (w*24)+k))
		k += 1
	}
	port.CellsSet(fw, (r*24)+13, line)
	return r
}

func FlCopyLine(fl *port.Cells, lines *port.Cells, l int32, first int32, cnt int32) int32 {
	// Append a copy of row l of `lines` to `fl` over the run (first, count) of `fw`; answers its row.
	var r int32 = plPush(fl, 16)
	var k int32 = 0
	for k < 16 {
		port.CellsSet(fl, (r*16)+k, port.CellsAt(lines, (l*16)+k))
		k += 1
	}
	port.CellsSet(fl, (r*16)+11, first)
	port.CellsSet(fl, (r*16)+12, cnt)
	return r
}

