func HlNew(c *port.Cells, kind int32, page int32, subject int32) int32 {
	// Append a health row: kind (`plh`), page, subject row; the six components and the score -1 (not computed).
	var r int32 = plPush(c, 12)
	var k int32 = 3
	HlSet(c, r, 0, kind)
	HlSet(c, r, 1, page)
	HlSet(c, r, 2, subject)
	for k < 10 {
		HlSet(c, r, k, -1)
		k += 1
	}
	return r
}

