func plBegin(t *strings.Builder, pr int32, d int32, started int32, code int32) int32 {
	if started == 1 {
		port.TextAscii(t, ",")
	}
	if pr == 1 {
		json.JsIndent(t, d+1)
	}
	port.TextAscii(t, "\"")
	PlkEmitName(t, code)
	port.TextAscii(t, "\":")
	if pr == 1 {
		port.TextAscii(t, " ")
	}
	return 1
}

func plQuad(t *strings.Builder, pr int32, c *port.Cells, p int32) int32 {
	port.TextAscii(t, "[")
	json.JsCpt(t, port.CellsAt(c, p))
	json.JsFsep(t, pr, 1)
	json.JsCpt(t, port.CellsAt(c, p+1))
	json.JsFsep(t, pr, 1)
	json.JsCpt(t, port.CellsAt(c, p+2))
	json.JsFsep(t, pr, 1)
	json.JsCpt(t, port.CellsAt(c, p+3))
	port.TextAscii(t, "]")
	return 0
}

func plField(t *strings.Builder, pr int32, c *port.Cells, stride int32, row int32, r int32, started int32) int32 {
	// One printed field of a row, by row `r` of `pl-fd`.
	var f int32 = PlFd[r*6+1]
	var kind int32 = PlFd[r*6+2]
	var key int32 = PlFd[r*6+3]
	var dflt int32 = PlFd[r*6+4]
	var arg int32 = PlFd[r*6+5]
	var p int32 = (row * stride) + f
	var s int32 = started
	var j int32 = 0
	if ((kind == 1) || ((kind == 2) || ((kind == 6) || ((kind == 8) || (kind == 9))))) && (port.CellsAt(c, p) == dflt) {
		return started
	}
	if kind == 1 {
		s = plBegin(t, pr, 2, s, key)
		port.TextI32(t, port.CellsAt(c, p))
		return s
	}
	if kind == 2 {
		s = plBegin(t, pr, 2, s, key)
		json.JsCpt(t, port.CellsAt(c, p))
		return s
	}
	if kind == 3 {
		s = plBegin(t, pr, 2, s, key)
		plQuad(t, pr, c, p)
		return s
	}
	if kind == 4 {
		if (port.CellsAt(c, p) == dflt) && (port.CellsAt(c, p+1) == arg) {
			return started
		}
		s = plBegin(t, pr, 2, s, key)
		port.TextAscii(t, "[")
		port.TextI32(t, port.CellsAt(c, p))
		json.JsFsep(t, pr, 1)
		port.TextI32(t, port.CellsAt(c, p+1))
		port.TextAscii(t, "]")
		return s
	}
	if kind == 5 {
		if port.CellsAt(c, p+1) == dflt {
			return started
		}
		s = plBegin(t, pr, 2, s, key)
		port.TextAscii(t, "[\"")
		evidence.EaEmitName(t, port.CellsAt(c, p))
		port.TextAscii(t, "\",")
		if pr == 1 {
			port.TextAscii(t, " ")
		}
		port.TextI32(t, port.CellsAt(c, p+1))
		port.TextAscii(t, "]")
		return s
	}
	if (kind == 6) || ((kind == 8) || (kind == 9)) {
		s = plBegin(t, pr, 2, s, key)
		port.TextAscii(t, "\"")
		if kind == 6 {
			model.DrEmitName(t, port.CellsAt(c, p))
		}
		if kind == 8 {
			PlhEmitName(t, port.CellsAt(c, p))
		}
		if kind == 9 {
			PlsEmitName(t, port.CellsAt(c, p))
		}
		port.TextAscii(t, "\"")
		return s
	}
	if kind == 7 {
		s = plBegin(t, pr, 2, s, key)
		port.TextAscii(t, "[")
		for j < arg {
			json.JsFsep(t, pr, j)
			port.TextI32(t, port.CellsAt(c, p+j))
			j += 1
		}
		port.TextAscii(t, "]")
		return s
	}
	return started
}

func plRow(t *strings.Builder, pr int32, a int32, c *port.Cells, row int32) int32 {
	// One row of own arena a (1 `cg` .. 6 `sl`) as an object, its fields in stride order.
	var first int32 = PlFx[(a-1)*4+0]
	var cnt int32 = PlFx[(a-1)*4+1]
	var stride int32 = PlFx[(a-1)*4+2]
	var s int32 = 0
	var k int32 = 0
	port.TextAscii(t, "{")
	for k < cnt {
		s = plField(t, pr, c, stride, row, first+k, s)
		k += 1
	}
	json.JsClose(t, pr, 2, s)
	return 0
}

func plArena(t *strings.Builder, pr int32, started int32, key int32, a int32, evea int32, c *port.Cells, etext *port.Cells) int32 {
	// `"key":[row, ...]` for own arena a (1..6), or, when a is 0, for an arena of the evidence's layout `evea` (8 words, 9 lines,
	// 12 paths) printed by the evidence's own table.
	var stride int32 = 0
	var n int32 = 0
	var i int32 = 0
	if a > 0 {
		stride = PlFx[(a-1)*4+2]
	}
	if a == 0 {
		if evea == 8 {
			stride = 24
		}
		if evea == 9 {
			stride = 16
		}
		if evea == 12 {
			stride = 24
		}
	}
	n = port.CellsLen(c) / stride
	plBegin(t, pr, 0, started, key)
	port.TextAscii(t, "[")
	for i < n {
		json.JsAelem(t, pr, 1, i)
		if a > 0 {
			plRow(t, pr, a, c, i)
		}
		if a == 0 {
			evidence.EvRow(t, pr, 2, evea, c, etext, i)
		}
		i += 1
	}
	json.JsAend(t, pr, 1, n)
	return 1
}

func PlEmitLayer(t *strings.Builder, pretty int32, s0 int32, cg *port.Cells, fw *port.Cells, fl *port.Cells, fv *port.Cells, fa *port.Cells, fx *port.Cells, hl *port.Cells, grl *port.Cells, sl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells, etext *port.Cells) int32 {
	// The layer's twelve arrays as members of the dump's object, after the evidence's; `s0` is 1 when a member came before.
	var s int32 = s0
	s = plArena(t, pretty, s, PlkCg(), 1, 0, cg, etext)
	s = plArena(t, pretty, s, PlkFw(), 0, 8, fw, etext)
	s = plArena(t, pretty, s, PlkFl(), 0, 9, fl, etext)
	s = plArena(t, pretty, s, PlkFv(), 2, 0, fv, etext)
	s = plArena(t, pretty, s, PlkFa(), 3, 0, fa, etext)
	s = plArena(t, pretty, s, PlkFx(), 4, 0, fx, etext)
	s = plArena(t, pretty, s, PlkHl(), 5, 0, hl, etext)
	s = glayer.GlArena(t, pretty, s, 1, grl)
	s = plArena(t, pretty, s, PlkSl(), 6, 0, sl, etext)
	s = glayer.GlArena(t, pretty, s, 2, gfl)
	s = glayer.GlArena(t, pretty, s, 3, ggp)
	s = glayer.GlArena(t, pretty, s, 4, grg)
	return s
}

func PlEmitOpen(t *strings.Builder, pretty int32, epages *port.Cells, views *port.Cells, pts *port.Cells, refs *port.Cells, etext *port.Cells, feats *port.Cells, glyphs *port.Cells, words *port.Cells, lines *port.Cells, marks *port.Cells, fonts *port.Cells, paths *port.Cells, images *port.Cells, oruns *port.Cells, oblocks *port.Cells, olines *port.Cells, owords *port.Cells, osyms *port.Cells, oalts *port.Cells, inks *port.Cells, components *port.Cells, rules *port.Cells, prims *port.Cells, tlines *port.Cells, cg *port.Cells, fw *port.Cells, fl *port.Cells, fv *port.Cells, fa *port.Cells, fx *port.Cells, hl *port.Cells, grl *port.Cells, sl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells) int32 {
	// The evidence dump, VERSION "2" (D203): the evidence's 24 arrays as `ev-emit` writes them, then the layer's twelve.
	var s int32 = 0
	port.TextAscii(t, "{")
	s = evidence.EvBegin(t, pretty, 0, s, evidence.EkVersion())
	port.TextAscii(t, "\"2\"")
	s = evidence.EvEmitBody(t, pretty, s, epages, views, pts, refs, etext, feats, glyphs, words, lines, marks, fonts, paths, images, oruns, oblocks, olines, owords, osyms, oalts, inks, components, rules, prims, tlines)
	s = PlEmitLayer(t, pretty, s, cg, fw, fl, fv, fa, fx, hl, grl, sl, gfl, ggp, grg, etext)
	return s
}

func PlEmit(t *strings.Builder, pretty int32, epages *port.Cells, views *port.Cells, pts *port.Cells, refs *port.Cells, etext *port.Cells, feats *port.Cells, glyphs *port.Cells, words *port.Cells, lines *port.Cells, marks *port.Cells, fonts *port.Cells, paths *port.Cells, images *port.Cells, oruns *port.Cells, oblocks *port.Cells, olines *port.Cells, owords *port.Cells, osyms *port.Cells, oalts *port.Cells, inks *port.Cells, components *port.Cells, rules *port.Cells, prims *port.Cells, tlines *port.Cells, cg *port.Cells, fw *port.Cells, fl *port.Cells, fv *port.Cells, fa *port.Cells, fx *port.Cells, hl *port.Cells, grl *port.Cells, sl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells) int32 {
	// The same, closed (`pl-emit-open`, then `}`).
	var s int32 = PlEmitOpen(t, pretty, epages, views, pts, refs, etext, feats, glyphs, words, lines, marks, fonts, paths, images, oruns, oblocks, olines, owords, osyms, oalts, inks, components, rules, prims, tlines, cg, fw, fl, fv, fa, fx, hl, grl, sl, gfl, ggp, grg)
	json.JsClose(t, pretty, 0, s)
	return 0
}

func PlEmitGfxOpen(t *strings.Builder, pretty int32, epages *port.Cells, views *port.Cells, pts *port.Cells, refs *port.Cells, etext *port.Cells, feats *port.Cells, glyphs *port.Cells, words *port.Cells, lines *port.Cells, marks *port.Cells, fonts *port.Cells, paths *port.Cells, images *port.Cells, oruns *port.Cells, oblocks *port.Cells, olines *port.Cells, owords *port.Cells, osyms *port.Cells, oalts *port.Cells, inks *port.Cells, components *port.Cells, rules *port.Cells, prims *port.Cells, tlines *port.Cells, grl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells) int32 {
	// The evidence dump as `pl-emit` writes it, version "2", with `grl gfl ggp grg` as the only layer arrays.
	var s int32 = 0
	port.TextAscii(t, "{")
	s = evidence.EvBegin(t, pretty, 0, s, evidence.EkVersion())
	port.TextAscii(t, "\"2\"")
	s = evidence.EvEmitBody(t, pretty, s, epages, views, pts, refs, etext, feats, glyphs, words, lines, marks, fonts, paths, images, oruns, oblocks, olines, owords, osyms, oalts, inks, components, rules, prims, tlines)
	s = glayer.GlArena(t, pretty, s, 1, grl)
	s = glayer.GlArena(t, pretty, s, 2, gfl)
	s = glayer.GlArena(t, pretty, s, 3, ggp)
	s = glayer.GlArena(t, pretty, s, 4, grg)
	return s
}

func PlEmitGfx(t *strings.Builder, pretty int32, epages *port.Cells, views *port.Cells, pts *port.Cells, refs *port.Cells, etext *port.Cells, feats *port.Cells, glyphs *port.Cells, words *port.Cells, lines *port.Cells, marks *port.Cells, fonts *port.Cells, paths *port.Cells, images *port.Cells, oruns *port.Cells, oblocks *port.Cells, olines *port.Cells, owords *port.Cells, osyms *port.Cells, oalts *port.Cells, inks *port.Cells, components *port.Cells, rules *port.Cells, prims *port.Cells, tlines *port.Cells, grl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells) int32 {
	// The same, closed (`pl-emit-gfx-open`, then `}`).
	var s int32 = PlEmitGfxOpen(t, pretty, epages, views, pts, refs, etext, feats, glyphs, words, lines, marks, fonts, paths, images, oruns, oblocks, olines, owords, osyms, oalts, inks, components, rules, prims, tlines, grl, gfl, ggp, grg)
	json.JsClose(t, pretty, 0, s)
	return 0
}
